$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_energy_public-dataset_v2.zip'
$out=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_5_CORE6_COLLISION_DIMENSION_NEED_SUMMARY_001.txt'
$expected='691F950A314015A7DE9D4CBABCC177846D74ABF7036B6A89E192B152A88E6D30';$sha=(Get-FileHash $zip -Algorithm SHA256).Hash.ToUpperInvariant();$md5=(Get-FileHash $zip -Algorithm MD5).Hash.ToUpperInvariant();if($sha-ne$expected){throw "ZIP SHA256 mismatch"}
function Parse([string]$l){$l -split ',(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)',10};function Clean([string]$s){if($null-eq$s){return ''};$s.Trim().Trim('"')}
$paths=@{'HydroRoR'='EST/Technologies/EST_HydroRoR.csv';'HydroDam'='EST/Technologies/EST_HydroDam.csv'};$data=@{}
$z=[IO.Compression.ZipFile]::OpenRead($zip);try{foreach($tech in $paths.Keys){$e=$z.GetEntry($paths[$tech]);if($null-eq$e){throw "Missing $($paths[$tech])"};$data[$tech]=@{};$r=[IO.StreamReader]::new($e.Open());try{while(($l=$r.ReadLine())-ne$null){$x=Parse $l;if($x.Count-lt 10){continue};$year=Clean $x[3];if($year-ne'1990'){continue};$p=Clean $x[2];$v=Clean $x[5];$data[$tech][$p]=$v}}finally{$r.Dispose()}}}finally{$z.Dispose()}
$core=@('Fuel_efficiency','LF_min','LF_max','Peak_contr','Ramp_rate','Resource');$diff=@();$all=@($data.HydroRoR.Keys+$data.HydroDam.Keys|Sort-Object -Unique);foreach($p in $all){$a=$data.HydroRoR[$p];$b=$data.HydroDam[$p];if($a-ne$b){$diff+=$p}}
$lines=@('TGCV MT4-5 - CORE6 COLLISION DIMENSION NEED AUDITOR 001',"SHA256=$sha","MD5=$md5",'COUNTRY_YEAR=EST|1990','TECHNOLOGIES=HydroRoR,HydroDam','CORE6_COLLISION_CONFIRMED=TRUE','DIFFERING_PARAMETERS=' + (($diff|Sort-Object)-join ','),'','INTERPRETATION=Diagnostic only. A differing parameter is not automatically a P_tau requirement. Potential_annual is explicitly excluded from automatic P_tau promotion because prior temporal audit identified future/retrospective dependencies.','NEXT_DECISION=Assess whether any differing non-CORE6 parameter is independently admissibility-relevant under the frozen pre-outcome information rule.','SUFFICIENT_FOR_P_tau=UNDETERMINED','STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION');[IO.File]::WriteAllLines($out,$lines)
Write-Output "OUTPUT=$out";Write-Output "SHA256=$sha";Write-Output "MD5=$md5";Write-Output 'CORE6_COLLISION_CONFIRMED=TRUE';Write-Output ('DIFFERING_PARAMETERS='+($diff|Sort-Object)-join ',');Write-Output 'SUFFICIENT_FOR_P_tau=UNDETERMINED';Write-Output 'STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION'